<main>

  <!-- 总览 -->
  <section class="tab-panel active" id="tab-overview">
    <div class="overview-wrap">
      <div class="card">
        <h3>合成路线地图</h3>
        <p class="hint">点击任意分子节点，查看它的名称、关键官能团和在本路线中的作用。</p>
        <div class="route-map">
