<script>
/* ================= 基础绘图工具 ================= */
const NS = 'http://www.w3.org/2000/svg';

function hexPoints(cx, cy, r, rot=-90){
  const pts = [];
  for(let i=0;i<6;i++){
    const a = (rot + i*60) * Math.PI/180;
    pts.push([cx + r*Math.cos(a), cy + r*Math.sin(a)]);
  }
  return pts;
}
function benzenePath(cx, cy, r, rot=-90){
  const pts = hexPoints(cx,cy,r,rot);
  return 'M' + pts.map(p=>p.join(',')).join('L') + 'Z';
}
function benzene(cx, cy, r, rot=-90, stroke='#334155'){
  const inner = benzenePath(cx, cy, r*0.70, rot);
  return `<path d="${benzenePath(cx,cy,r,rot)}" fill="#fff" stroke="${stroke}" stroke-width="1.8"/>` +
         `<path d="${inner}" fill="none" stroke="${stroke}" stroke-width="1" stroke-dasharray="2 4"/>`;
}
function line(x1,y1,x2,y2,color='#334155',w=1.8){
  return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${w}" stroke-linecap="round"/>`;
}
function txt(x,y,str,color='#1e293b',size=13,anchor='middle',weight='normal'){
  return `<text x="${x}" y="${y}" fill="${color}" font-size="${size}" text-anchor="${anchor}" font-weight="${weight}" font-family="system-ui,-apple-system,'Microsoft YaHei',sans-serif">${str}</text>`;
}

/* ================= 标签页 ================= */
function initTabs(){
  document.querySelectorAll('.tab-btn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      document.querySelectorAll('.tab-btn').forEach(b=>b.classList.remove('active'));
      document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));
      btn.classList.add('active');
      const panel = document.getElementById(btn.dataset.tab);
      if(panel) panel.classList.add('active');

      if(btn.dataset.tab === 'tab-overview') drawOverview();
      if(btn.dataset.tab === 'tab-ac'){ drawA(); drawC(false); }
      if(btn.dataset.tab === 'tab-fg'){ drawD(false); drawFG(0); }
      if(btn.dataset.tab === 'tab-boc'){ drawBoc(0); }
      if(btn.dataset.tab === 'tab-synth'){ drawSynth(0); }
    });
  });
}

/* ================= 总览 ================= */
const overviewData = {
  A:{name:'对氯硝基苯', formula:'C₆H₄ClNO₂', note:'苯环上 —Cl 与 —NO₂ 处于对位。', role:'起始原料，经 Fe/HCl 还原得到苯胺 B。'},
  B:{name:'对氯苯胺', formula:'C₆H₆ClN', note:'—NO₂ 被还原为 —NH₂。', role:'亲核试剂，与 2-氟苯甲酰氯形成酰胺 C。'},
  C:{name:'2-氟-N-(4-氯苯基)苯甲酰胺', formula:'C₁₃H₉ClFNO', note:'B 的 —NH₂ 与 2-氟苯甲酰氯缩合，脱去 HCl。', role:'提供酰胺 N—H，参与后续氮杂-迈克尔加成。'},
  D:{name:'2-氨基乙醇', formula:'C₂H₇NO', note:'含 —OH 和 —NH₂。', role:'经 Boc 保护、氧化得到 E。'},
  E:{name:'N-Boc-2-氨基乙醛', formula:'C₇H₁₃NO₃', note:'—NH₂ 被 Boc 保护，—OH 氧化为醛基。', role:'与 CH₃NO₂ 发生缩合。'},
  F:{name:'N-Boc-2-氨基-3-硝基丙-1-醇', formula:'C₈H₁₆N₂O₅', note:'含 —OH、—NO₂ 和 BocNH—。', role:'经 MsCl/碱发生消去。'},
  G:{name:'N-Boc-硝基烯烃', formula:'C₈H₁₄N₂O₄', note:'C=C 与 —NO₂ 共轭，是缺电子烯烃。', role:'与 C 的酰胺 N—H 发生氮杂-迈克尔加成。'},
  H:{name:'加成产物', formula:'', note:'C 的 N—H 加到 G 的 β-碳上，得到 H。', role:'硝基还原后环化。'},
  I:{name:'Boc 保护的环化产物', formula:'', note:'Fe/乙酸还原硝基，随后分子内环化形成七元环。', role:'酸性脱 Boc。'},
  J:{name:'脱 Boc 产物', formula:'', note:'伯胺恢复，准备与 CH₃C(OCH₃)₃ 成环。', role:'与 CH₃C(OCH₃)₃ 反应生成咪唑环。'},
  K:{name:'咪达唑仑中间体', formula:'', note:'咪唑环与苯二氮䓬环稠合。', role:'目标中间体。'}
};

function miniSvg(key){
  const w=64,h=52;
  let s = `<svg viewBox="0 0 ${w} ${h}" width="${w}" height="${h}">`;
  if(['A','B','C','I','J','K'].includes(key)){
    const cx=32, cy=26, r=14;
    s += `<path d="${benzenePath(cx,cy,r)}" fill="#fff" stroke="#334155" stroke-width="1.5"/>`;
    const labels = {
      A:[['Cl','#16a34a',32,7],['NO₂','#dc2626',32,48]],
      B:[['Cl','#16a34a',32,7],['NH₂','#2563eb',32,48]],
      C:[['F','#ea580c',32,7],['Cl','#16a34a',32,48]],
      I:[['Boc','#7c3aed',32,7],['Cl','#16a34a',32,48]],
      J:[['NH₂','#2563eb',32,7],['Cl','#16a34a',32,48]],
      K:[['咪唑','#7c3aed',32,7],['Cl','#16a34a',32,48]]
    };
    (labels[key]||[]).forEach(([t,c,x,y])=>{
      s += `<text x="${x}" y="${y}" fill="${c}" font-size="8" text-anchor="middle">${t}</text>`;
    });
  }else{
    s += `<path d="M10 31 L22 18 L34 34 L46 22" fill="none" stroke="#334155" stroke-width="1.6"/>`;
    s += `<text x="32" y="48" fill="#64748b" font-size="7" text-anchor="middle">${key}</text>`;
  }
  s += `</svg>`;
  return s;
}

let playTimer = null;

function renderRouteRow(id, keys){
  const row = document.getElementById(id);
  if(!row) return;
  row.innerHTML = '';
  keys.forEach((k, idx)=>{
    const node = document.createElement('div');
    node.className = 'route-node';
    node.dataset.key = k;
    node.innerHTML = `<div class="node-mini">${miniSvg(k)}</div><div class="node-label">${k}</div>`;
    node.addEventListener('click', ()=> selectNode(k));
    row.appendChild(node);
    if(idx < keys.length-1){
      const arrow = document.createElement('div');
      arrow.className = 'route-arrow';
      arrow.textContent = '→';
      row.appendChild(arrow);
    }
  });
  if(id === 'route-row-2'){
    const extra = document.createElement('div');
    extra.className = 'route-extra';
    extra.textContent = 'G 与 C 汇合生成 H';
    row.appendChild(extra);
  }
}

function drawOverview(){
  renderRouteRow('route-row-1', ['A','B','C','H','I','J','K']);
  renderRouteRow('route-row-2', ['D','E','F','G']);
  selectNode('A');
}

function selectNode(key){
  document.querySelectorAll('.route-node').forEach(n=>{
    n.classList.toggle('active', n.dataset.key === key);
  });
  const d = overviewData[key];
  if(!d) return;
  const box = document.getElementById('overview-detail');
  box.innerHTML = `
    <div class="detail-title">${key} · ${d.name}</div>
    <div class="detail-meta">${d.formula ? '分子式：' + d.formula : ''}</div>
    <div class="detail-body">
      <p>${d.note}</p>
      <p><strong>在路线中的作用：</strong>${d.role}</p>
    </div>
  `;
}

function playRoute(){
  stopRoute();
  const seq = ['A','B','C','D','E','F','G','H','I','J','K'];
  let i = 0;
  playTimer = setInterval(()=>{
    if(i >= seq.length){ stopRoute(); return; }
    selectNode(seq[i]);
    i++;
  }, 720);
}
function stopRoute(){
  if(playTimer){ clearInterval(playTimer); playTimer = null; }
}

/* ================= A ================= */
function drawA(){
  const cx=110, cy=92, r=38;
  let s = benzene(cx,cy,r);
  s += line(cx, cy-r, cx, cy-r-18);
  s += txt(cx, cy-r-24, 'Cl', '#16a34a', 16, 'middle', '700');
  s += line(cx, cy+r, cx, cy+r+18);
  s += txt(cx, cy+r+31, 'NO₂', '#dc2626', 15, 'middle', '700');
  s += txt(cx+48, cy-r+4, '1', '#94a3b8', 11);
  s += txt(cx+48, cy+r+4, '4', '#94a3b8', 11);
  document.getElementById('svg-A').innerHTML = s;
}

function initA(){
  document.querySelectorAll('#name-options .btn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const fb = document.getElementById('feedback-A');
      if(btn.dataset.answer === 'right-4'){
        fb.innerHTML = '<span style="color:#16a34a">正确。</span> 以硝基为母体，Cl 在 4 位，所以叫 4-氯硝基苯（也可叫对氯硝基苯）。';
        document.getElementById('conclusion-A').innerHTML = '<div class="conclusion"><strong>A：</strong>4-氯硝基苯（或 1-氯-4-硝基苯）。</div>';
      }else{
        fb.innerHTML = '<span style="color:#dc2626">再看位置：</span> Cl 与 NO₂ 在苯环两侧相对，是 1,4-关系。';
      }
    });
  });
}

/* ================= C ================= */
function drawC(formed=false){
  const svg = document.getElementById('svg-C');
  const cxL=95, cy=110, r=32;
  const cxR=305, cy=110, r=32;
  let s = '';
  s += benzene(cxL, cy, r);
  s += benzene(cxR, cy, r);

  const p2 = [cxL + r*Math.cos(-60*Math.PI/180), cy + r*Math.sin(-60*Math.PI/180)];
  s += line(p2[0], p2[1], p2[0]+17, p2[1]-10);
  s += txt(p2[0]+27, p2[1]-14, 'F', '#ea580c', 15, 'middle', '700');

  const q4 = [cxR + r, cy];
  s += line(q4[0], q4[1], q4[0]+17, q4[1]);
  s += txt(q4[0]+27, q4[1]+5, 'Cl', '#16a34a', 15, 'middle', '700');

  if(!formed){
    const p1 = [cxL + r, cy];
    s += line(p1[0], p1[1], p1[0]+27, p1[1]-9);
    s += txt(p1[0]+40, p1[1]-13, 'C', '#1e293b', 14, 'middle', '700');
    s += line(p1[0]+40, p1[1]-18, p1[0]+40, p1[1]-36);
    s += txt(p1[0]+40, p1[1]-43, 'O', '#dc2626', 14, 'middle', '700');
    s += line(p1[0]+40, p1[1]-9, p1[0]+58, p1[1]-9);
    s += txt(p1[0]+65, p1[1]-5, 'Cl', '#16a34a', 14, 'middle', '700');

    const q1 = [cxR - r, cy];
    s += line(q1[0], q1[1], q1[0]-17, q1[1]);
    s += txt(q1[0]-30, q1[1]+5, 'NH₂', '#2563eb', 14, 'middle', '700');
    s += txt(200, 40, '2-氟苯甲酰氯 + 4-氯苯胺', '#64748b', 13);
  }else{
    const p1 = [cxL + r, cy];
    const c = [p1[0]+32, p1[1]-10];
    s += line(p1[0], p1[1], c[0], c[1]);
    s += line(c[0], c[1], c[0], c[1]-20);
    s += txt(c[0], c[1]-27, 'O', '#dc2626', 14, 'middle', '700');
    s += line(c[0], c[1], c[0]+30, c[1]-11);
    s += txt(c[0]+17, c[1]-2, 'N', '#2563eb', 14, 'middle', '700');
    s += txt(c[0]+28, c[1]-24, 'H', '#1e293b', 11);
    const q1 = [cxR - r, cy];
    s += line(c[0]+30, c[1]-11, q1[0]-6, q1[1]);
    s += txt(200, 38, 'C：2-氟-N-(4-氯苯基)苯甲酰胺', '#2563eb', 13);
    s += `<g class="hcl-float">${txt(c[0]+58, c[1]+10, 'HCl', '#64748b', 12)}</g>`;
  }
  svg.innerHTML = s;
}

function initC(){
  document.getElementById('btn-amidation').addEventListener('click', ()=>{
    drawC(true);
    document.getElementById('feedback-C').innerHTML = '酰胺键形成：<strong>—C(=O)—NH—</strong>。B 的氨基氮与酰氯的羰基碳成键，HCl 离去。';
    document.getElementById('conclusion-C').innerHTML = '<div class="conclusion"><strong>C 的结构简式：</strong>2-氟-N-(4-氯苯基)苯甲酰胺。</div>';
  });
  document.getElementById('btn-reset-C').addEventListener('click', ()=>{
    drawC(false);
    document.getElementById('feedback-C').textContent = '';
    document.getElementById('conclusion-C').innerHTML = '';
  });
}

/* ================= D ================= */
function drawD(highlight=false){
  let s = '';
  s += line(62,82,100,62);
  s += line(100,62,140,100);
  s += line(140,100,178,80);
  s += txt(44,87,'HO','#dc2626',15,'middle','700');
  s += txt(100,52,'CH₂','#1e293b',13);
  s += txt(140,118,'CH₂','#1e293b',13);
