/* ================= 同分异构体 ================= */
const isoChips = [
  {id:0, sub:'OCH3', used:false},
  {id:1, sub:'OCH3', used:false},
  {id:2, sub:'OH', used:false}
];
let isoPlaced = {1:[],2:[],3:[]};
let selectedChip = null;
let foundKeys = new Set();

const isoStructures = [
  {id:1, c1:['OCH3','OCH3'], c2:[], c3:['OH'], group:'同碳OCH3', cat:'两个 —OCH₃ 在端碳，—OH 在另一端碳', formula:'(CH₃O)₂CH—CH₂—CH₂OH', nmr:false},
  {id:2, c1:['OCH3','OCH3'], c2:['OH'], c3:[], group:'同碳OCH3', cat:'两个 —OCH₃ 在端碳，—OH 在中间碳', formula:'(CH₃O)₂CH—CH(OH)—CH₃', nmr:false},
  {id:3, c1:[], c2:['OCH3','OCH3'], c3:['OH'], group:'同碳OCH3', cat:'两个 —OCH₃ 在中间碳，—OH 在端碳', formula:'(CH₃O)₂C(CH₃)—CH₂OH', nmr:true},
  {id:4, c1:['OCH3'], c2:['OCH3'], c3:['OH'], group:'三', cat:'三个取代基分居三个碳（—OH 在端碳）', formula:'CH₃O—CH₂—CH(OCH₃)—CH₂OH', nmr:false},
  {id:5, c1:['OCH3'], c2:['OH'], c3:['OCH3'], group:'三', cat:'三个取代基分居三个碳（—OH 在中间碳）', formula:'CH₃O—CH₂—CH(OH)—CH₂—OCH₃', nmr:false},
  {id:6, c1:['OCH3','OH'], c2:[], c3:['OCH3'], group:'同碳OH', cat:'—OCH₃ 与 —OH 同碳（端碳）', formula:'HO—CH(OCH₃)—CH₂—CH₂OCH₃', nmr:false},
  {id:7, c1:['OCH3','OH'], c2:['OCH3'], c3:[], group:'同碳OH', cat:'—OCH₃ 与 —OH 同碳（端碳），另一 —OCH₃ 在中间碳', formula:'HO—CH(OCH₃)—CH(OCH₃)—CH₃', nmr:false},
  {id:8, c1:['OCH3'], c2:['OCH3','OH'], c3:[], group:'同碳OH', cat:'—OCH₃ 与 —OH 同碳（中间碳）', formula:'CH₃O—CH₂—C(OH)(OCH₃)—CH₃', nmr:false},
  {id:9, c1:['OCH3','OCH3','OH'], c2:[], c3:[], group:'同碳全部', cat:'三个取代基同碳', formula:'(CH₃O)₂C(OH)—CH₂—CH₃', nmr:true}
];

function normalizeKey(c1,c2,c3){
  const a1 = c1.slice().sort();
  const a2 = c2.slice().sort();
  const a3 = c3.slice().sort();
  const a = JSON.stringify([a1,a2,a3]);
  const b = JSON.stringify([a3,a2,a1]);
  return a < b ? a : b;
}
isoStructures.forEach(s=>{
  s.key = normalizeKey(s.c1, s.c2, s.c3);
});

function renderChips(){
  document.querySelectorAll('#iso-chips .chip').forEach(btn=>{
    const id = +btn.dataset.chip;
    const chip = isoChips[id];
    btn.disabled = chip.used;
    btn.classList.toggle('used', chip.used);
    btn.classList.toggle('selected', selectedChip === id);
  });
}

function renderBuilder(){
  [1,2,3].forEach(c=>{
    const node = document.querySelector(`.carbon-node[data-c="${c}"]`);
    if(!node) return;
    const slots = node.querySelector('.slots');
    slots.innerHTML = '';
    isoPlaced[c].forEach(chipId=>{
      const chip = isoChips[chipId];
      const span = document.createElement('span');
      span.className = 'slot';
      span.textContent = chip.sub === 'OCH3' ? '—OCH₃' : '—OH';
      span.style.color = chip.sub === 'OH' ? '#dc2626' : '#7c3aed';
      span.addEventListener('click', (e)=>{
        e.stopPropagation();
        isoPlaced[c] = isoPlaced[c].filter(id=>id !== chipId);
        isoChips[chipId].used = false;
        renderBuilder();
      });
      slots.appendChild(span);
    });
  });
  renderChips();
}

function isoFeedback(msg, color){
  const fb = document.getElementById('iso-feedback');
  fb.innerHTML = color ? `<span style="color:${color}">${msg}</span>` : msg;
}

function getCurrentKey(){
  const subs = [1,2,3].map(c=> isoPlaced[c].map(id=> isoChips[id].sub));
  return normalizeKey(subs[0], subs[1], subs[2]);
}

function appendFoundCard(s){
  const list = document.getElementById('iso-found');
  if(list.querySelector(`[data-sid="${s.id}"]`)) return;
  const card = document.createElement('div');
  card.className = 'iso-card' + (s.nmr ? ' nmr-hit' : '');
  card.dataset.sid = s.id;
  card.innerHTML = `
    <div class="iso-card-head">结构 ${s.id} ${s.nmr ? '<span class="badge">NMR 符合</span>' : ''}</div>
    <div class="iso-formula">${s.formula}</div>
    <div class="iso-cat">${s.cat}</div>
  `;
  card.addEventListener('click', ()=> showIsoDetail(s));
  list.appendChild(card);
}

function checkIsoComplete(){
  if(!isoChips.every(c=>c.used)) return;
  const key = getCurrentKey();
  const found = isoStructures.find(s=>s.key === key);
  if(found){
    if(!foundKeys.has(key)){
      foundKeys.add(key);
      appendFoundCard(found);
      isoFeedback(`合法结构：${found.formula}（${found.cat}）`, '#16a34a');
    }else{
      isoFeedback(`这个结构与已找到的「${found.formula}」相同。`, '#64748b');
    }
    if(found.nmr){
      isoFeedback(`合法结构：${found.formula}。它的氢谱为 4 组峰，面积比 6:3:2:1。`, '#16a34a');
    }
  }else{
    isoFeedback('这个组合不合法或不是题目条件下的结构，检查一下价数或位置。', '#dc2626');
  }
}

function renderIsoList(structs, title){
  const list = document.getElementById('iso-list');
  list.innerHTML = '';
  if(!structs || structs.length === 0){
    list.innerHTML = '<p class="hint">没有符合条件的结构。</p>';
    return;
  }
  structs.forEach(s=>{
    const card = document.createElement('div');
    card.className = 'iso-card' + (s.nmr ? ' nmr-hit' : '');
    card.dataset.sid = s.id;
    card.innerHTML = `
      <div class="iso-card-head">结构 ${s.id} ${s.nmr ? '<span class="badge">NMR 符合</span>' : ''}</div>
      <div class="iso-formula">${s.formula}</div>
      <div class="iso-cat">${s.cat}</div>
    `;
    card.addEventListener('click', ()=> showIsoDetail(s));
    list.appendChild(card);
  });
}

function showIsoDetail(s){
  const d = document.getElementById('iso-detail');
  d.innerHTML = `<strong>${s.formula}</strong><br>${s.cat}` +
    (s.nmr
      ? '<br><span style="color:#047857">两个 —OCH₃ 等价（6H），—CH₃（3H），—CH₂—（2H），—OH（1H）→ 4 组峰，6:3:2:1。</span>'
      : '<br><span class="muted">不等价氢较多，峰组数不等于 4，不符合 NMR 条件。</span>');
}

function initIso(){
  // 筹码点击
  document.querySelectorAll('#iso-chips .chip').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const id = +btn.dataset.chip;
      if(isoChips[id].used) return;
      selectedChip = (selectedChip === id ? null : id);
      renderChips();
    });
  });

  // 碳节点点击
  document.querySelectorAll('.carbon-node').forEach(node=>{
    node.addEventListener('click', ()=>{
      if(selectedChip === null) return;
      const c = +node.dataset.c;
      const max = c === 2 ? 2 : 3;
      if(isoPlaced[c].length >= max){
        isoFeedback('这个碳上已经放不下更多取代基了。', '#dc2626');
        return;
      }
      isoPlaced[c].push(selectedChip);
      isoChips[selectedChip].used = true;
      selectedChip = null;
      renderBuilder();
      checkIsoComplete();
    });
  });

  document.getElementById('btn-clear-iso').addEventListener('click', ()=>{
    isoPlaced = {1:[],2:[],3:[]};
    isoChips.forEach(c=>c.used = false);
    selectedChip = null;
    renderBuilder();
    document.getElementById('iso-found').innerHTML = '';
    foundKeys = new Set();
    isoFeedback('已清空。再试着放完三个取代基。');
  });

  document.getElementById('btn-enumerate').addEventListener('click', ()=>{
    renderIsoList(isoStructures, '全部 9 种');
    renderFilters();
    document.getElementById('iso-detail').innerHTML = '按取代基分布分类：<br>分居三碳 2 种；两个 —OCH₃ 同碳 3 种；—OCH₃ 与 —OH 同碳 3 种；三个同碳 1 种。<br>点击结构卡片查看氢谱。';
    document.getElementById('conclusion-iso').innerHTML = '<div class="conclusion"><strong>第 (6) 问：</strong>符合条件的同分异构体共有 <strong>9 种</strong>（按价键规则完整计数）。</div>';
  });

  document.getElementById('btn-nmr').addEventListener('click', ()=>{
    const hits = isoStructures.filter(s=>s.nmr);
    renderIsoList(hits, 'NMR 6:3:2:1');
    renderFilters(true);
    document.getElementById('iso-detail').innerHTML = hits.map(s=>
      `<strong>${s.formula}</strong>：两个 —OCH₃ 等价（6H），—CH₃（3H），—CH₂—（2H），—OH（1H）。`
    ).join('<br><br>');
    document.getElementById('conclusion-iso').innerHTML = '<div class="conclusion"><strong>NMR 符合 6:3:2:1 的结构可写：</strong><br>(CH₃O)₂C(CH₃)—CH₂OH<br>或 (CH₃O)₂C(OH)—CH₂—CH₃（任写一种）。</div>';
  });
}

function renderFilters(nmrOnly){
  const wrap = document.getElementById('iso-filters');
  wrap.innerHTML = '';
  const groups = [
    {key:'all', label:'全部 9 种'},
    {key:'三', label:'分居三碳 · 2 种'},
    {key:'同碳OCH3', label:'两个 OCH₃ 同碳 · 3 种'},
    {key:'同碳OH', label:'OCH₃ 与 OH 同碳 · 3 种'},
    {key:'同碳全部', label:'三个同碳 · 1 种'}
  ];
  groups.forEach(g=>{
    const btn = document.createElement('button');
    btn.className = 'filter-btn';
    btn.textContent = g.label;
    btn.addEventListener('click', ()=>{
      wrap.querySelectorAll('.filter-btn').forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      let arr;
      if(g.key === 'all') arr = isoStructures;
      else arr = isoStructures.filter(s=>s.group === g.key);
      if(nmrOnly) arr = arr.filter(s=>s.nmr);
      renderIsoList(arr);
    });
    wrap.appendChild(btn);
  });
}

/* ================= 合成设计 ================= */
let synthStage = 0;
const synthSeq = ['ox','con','red'];

function drawSynth(stage){
  const svg = document.getElementById('svg-synth');
  const cx=150, cy=120, r=40;
  let s = '';

  // 苯环
  s += `<path d="${benzenePath(cx,cy,r,0)}" fill="#fff" stroke="#334155" stroke-width="2"/>`;
  // 侧链在 1 位（右侧，角度 0°）
  const p1 = [cx + r, cy];
  // 2 位（右下，角度 60°）Cl
  const p2 = [cx + r*Math.cos(60*Math.PI/180), cy + r*Math.sin(60*Math.PI/180)];
  // 4 位（左侧，角度 180°）Cl
  const p4 = [cx + r*Math.cos(180*Math.PI/180), cy + r*Math.sin(180*Math.PI/180)];

  s += line(p2[0], p2[1], p2[0]+14, p2[1]+10);
  s += txt(p2[0]+22, p2[1]+16, 'Cl', '#16a34a', 14, 'middle', '700');
  s += line(p4[0], p4[1], p4[0]-14, p4[1]);
  s += txt(p4[0]-24, p4[1]+5, 'Cl', '#16a34a', 14, 'middle', '700');

  if(stage === 0){
    s += line(p1[0], p1[1], p1[0]+28, p1[1]);
    s += txt(p1[0]+46, p1[1]+5, 'CH₂OH', '#dc2626', 14, 'middle', '700');
    s += txt(370, 150, '+ CH₃NO₂', '#7c3aed', 14);
    s += txt(260, 40, '二氯苄醇', '#64748b', 13);
  }else if(stage === 1){
    s += line(p1[0], p1[1], p1[0]+28, p1[1]);
    s += txt(p1[0]+44, p1[1]+5, 'CHO', '#dc2626', 14, 'middle', '700');
    s += txt(260, 40, '氧化：—CH₂OH → —CHO', '#2563eb', 13);
  }else if(stage === 2){
    s += line(p1[0], p1[1], p1[0]+30, p1[1]);
    s += txt(p1[0]+58, p1[1]-22, 'CH(OH)', '#dc2626', 13, 'middle', '700');
    s += line(p1[0]+58, p1[1]-18, p1[0]+80, p1[1]-8);
    s += txt(p1[0]+98, p1[1]-4, 'CH₂NO₂', '#dc2626', 13, 'middle', '700');
    s += txt(260, 40, '缩合：醛 + CH₃NO₂ → 硝基醇', '#7c3aed', 13);
  }else{
    s += line(p1[0], p1[1], p1[0]+30, p1[1]);
    s += txt(p1[0]+58, p1[1]-22, 'CH(OH)', '#dc2626', 13, 'middle', '700');
    s += line(p1[0]+58, p1[1]-18, p1[0]+80, p1[1]-8);
    s += txt(p1[0]+98, p1[1]-4, 'CH₂NH₂', '#2563eb', 13, 'middle', '700');
    s += txt(260, 40, '还原：—NO₂ → —NH₂', '#16a34a', 13);
  }
  svg.innerHTML = s;
}

function updateSynthSteps(){
  const wrap = document.getElementById('synth-steps');
  const labels = {
    ox:'氧化',
    con:'与 CH₃NO₂ 缩合',
    red:'还原硝基'
  };
  wrap.innerHTML = '';
  synthSeq.slice(0, synthStage).forEach((step, i)=>{
    const pill = document.createElement('span');
    pill.className = 'synth-step-pill';
    pill.textContent = labels[step];
    wrap.appendChild(pill);
    if(i < synthStage-1){
      const arr = document.createElement('span');
      arr.className = 'synth-step-arrow';
      arr.textContent = '→';
      wrap.appendChild(arr);
    }
  });
}

function initSynth(){
  document.querySelectorAll('[data-step]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const step = btn.dataset.step;
      const fb = document.getElementById('synth-feedback');
      if(synthStage >= 3) return;

      if(synthSeq[synthStage] === step){
        btn.classList.add('done');
        synthStage++;
        drawSynth(synthStage);
        updateSynthSteps();

        if(synthStage === 1) fb.innerHTML = '苄醇被氧化为醛。下一步要引入硝基。';
        if(synthStage === 2) fb.innerHTML = '醛与 CH₃NO₂ 缩合，得到硝基醇。下一步还原硝基。';
        if(synthStage === 3){
          fb.innerHTML = '<span style="color:#16a34a">路线完成！</span> 苄醇 → 氧化 → 缩合 → 还原，得到目标氨基醇。';
          document.getElementById('conclusion-synth').innerHTML = '<div class="conclusion"><strong>合成路线：</strong>二氯苄醇 <span class="muted">—MnO₂→</span> 二氯苯甲醛 <span class="muted">+CH₃NO₂/碱→</span> 硝基醇 <span class="muted">—Fe/HCl→</span> 二氯苯基—CH(OH)—CH₂NH₂。</div>';
        }
      }else{
        btn.classList.add('shake');
        setTimeout(()=>btn.classList.remove('shake'), 380);
        fb.innerHTML = '<span style="color:#dc2626">顺序不对。</span> 先想想：苄醇要变成醛，才能与 CH₃NO₂ 缩合引入硝基。';
      }
    });
  });
}

